        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeEncryptorDecryptor.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface EncryptorDecryptor: handle missing in uniffiFree")
            }
