/**
 * These are the errors returned by our public API.
 */
public 
enum DbCryptoApiError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * NSS not initialized.
     */
    case NssUninitialized
    /**
     * NSS error during authentication
     */
    case NssAuthenticationError(reason: String
    )
    /**
     * error during authentication (in PrimaryPasswordAuthenticator)
     */
    case AuthenticationError(reason: String
    )
    /**
     * authentication has been cancelled.
     */
    case AuthenticationCanceled
    /**
     * Encryption key is missing.
     */
    case MissingKey
    /**
     * Encryption key is not valid.
     */
    case InvalidKey
    /**
     * encryption failed
     */
    case EncryptionFailed(reason: String
    )
    /**
     * decryption failed
     */
    case DecryptionFailed(reason: String
    )
    /**
     * An operation was interrupted at the request of the consuming app.
     */
    case Interrupted(reason: String
    )
    /**
     * something internal went wrong which doesn't have a public error value
     * because the consuming app can not reasonably take any action to resolve it.
     * The underlying error will have been logged and reported.
     * (ideally would just be `Unexpected`, but that would be a breaking change)
     */
    case UnexpectedDbCryptoApiError(reason: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension DbCryptoApiError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDbCryptoApiError: FfiConverterRustBuffer {
    typealias SwiftType = DbCryptoApiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DbCryptoApiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NssUninitialized
        case 2: return .NssAuthenticationError(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 3: return .AuthenticationError(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 4: return .AuthenticationCanceled
        case 5: return .MissingKey
        case 6: return .InvalidKey
        case 7: return .EncryptionFailed(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 8: return .DecryptionFailed(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 9: return .Interrupted(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 10: return .UnexpectedDbCryptoApiError(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DbCryptoApiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .NssUninitialized:
            writeInt(&buf, Int32(1))
        
        
        case let .NssAuthenticationError(reason):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .AuthenticationError(reason):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .AuthenticationCanceled:
            writeInt(&buf, Int32(4))
        
        
        case .MissingKey:
            writeInt(&buf, Int32(5))
        
        
        case .InvalidKey:
            writeInt(&buf, Int32(6))
        
        
        case let .EncryptionFailed(reason):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .DecryptionFailed(reason):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Interrupted(reason):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .UnexpectedDbCryptoApiError(reason):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


